const createSelectors = (store) => {
  store.use = {}
  Object.keys(store.getState()).forEach((k) => {
    store.use[k] = () => store((s) => s[k])
  })
  return store
}

const useAuthStore = create(
  persist(
    (set) => ({ user: null, theme: 'light', loading: false }),
    {
      name: 'auth-storage',
      partialize: (s) => ({ user: s.user, theme: s.theme }),
      storage: createJSONStorage(() => sessionStorage),
      version: 2,
      migrate: (persistedState, version) =>
        version === 1 ? { ...persistedState, newField: 'default' } : persistedState,
      onRehydrateStorage: () => (state, error) => {
        if (error) console.error('hydration failed', error)
      },
    },
  ),
)

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      staleTime: 60_000,
      gcTime: 5 * 60_000,
      retry: (count, error) => error.status !== 404 && count < 3,
      retryDelay: (attempt) => Math.min(1000 * 2 ** attempt, 30_000),
      refetchOnWindowFocus: false,
    },
  },
  // v5 bỏ onError toàn cục — bắt lỗi qua QueryCache listener
  queryCache: new QueryCache({
    onError: (error) => toast.error(error.message),
  }),
})

const queryClient = new QueryClient({
  queryCache: new QueryCache({
    onError: (error, query) => {
      if (query.meta?.showErrorToast) toast.error(error.message)
    },
  }),
})

